import os, runpy, sys
from pathlib import Path
mode = sys.argv[1] if len(sys.argv) > 1 else 'post'
script = None
root = os.environ.get('ZCODE_PROJECT_DIR') or os.environ.get('CLAUDE_PROJECT_DIR')
if root:
    p = Path(root) / '科研工具箱' / 'hooks' / 'zcode_audit_l1.py'
    if p.is_file():
        script = p
if script is None:
    d = Path.cwd()
    for base in (d, *d.parents):
        p = base / '科研工具箱' / 'hooks' / 'zcode_audit_l1.py'
        if p.is_file():
            script = p
            break
if script is None:
    print('[zcode_audit_l1-bootstrap] hook 脚本定位失败(env 与 cwd 上溯均未命中), fail-open 放行', file=sys.stderr)
    sys.exit(0)
sys.argv = [str(script), mode]
try:
    runpy.run_path(str(script), run_name='__main__')
except Exception as exc:
    print('[zcode_audit_l1-bootstrap] hook 执行异常, fail-open 放行: %r' % (exc,), file=sys.stderr)
    sys.exit(0)

